window.YV_TEXT=window.YV_TEXT||{};Object.assign(window.YV_TEXT,{"文献候选基因":{"en":"Literature candidate genes","fr":"Gènes candidats publiés","es":"Genes candidatos publicados","eu":"Literaturako gene hautagaiak"},"文献候选集；需在目标菌株与条件中验证":{"en":"Published candidates; validate in target strains and conditions","fr":"Candidats publiés ; valider dans les souches et conditions cibles","es":"Candidatos publicados; validar en cepas y condiciones de destino","eu":"Argitaratutako hautagaiak; balioztatu xede-andui eta baldintzetan"},"Shabestary Data 1 重分析 Jackson 2020 数据；G1/G2 是亚群编号，不是细胞周期阶段。":{"en":"Shabestary Data 1 reanalyses Jackson 2020 data; G1/G2 are subpopulation identifiers, not cell-cycle phases.","fr":"Les données 1 de Shabestary réanalysent Jackson 2020 ; G1/G2 identifient des sous-populations, pas des phases du cycle.","es":"Data 1 de Shabestary reanaliza Jackson 2020; G1/G2 son subpoblaciones, no fases del ciclo.","eu":"Shabestary Data 1ek Jackson 2020 berranalizatzen du; G1/G2 azpipopulazioak dira, ez zelula-zikloaren faseak."},"Data 4 为蛋白核定位参考；未推断转录因子RNA丰度或因果活性。Tos9 的三条记录身份未决，未强行映射。":{"en":"Data 4 is protein nuclear-localisation reference evidence; TF RNA abundance or causal activity is not inferred. Three Tos9 identities remain unresolved.","fr":"Les données 4 documentent la localisation nucléaire des protéines ; ni abondance ARN des TF ni activité causale n’en sont inférées. Trois identités Tos9 restent non résolues.","es":"Data 4 aporta localización nuclear de proteínas; no infiere abundancia de ARN de TF ni actividad causal. Tres identidades Tos9 siguen sin resolver.","eu":"Data 4 proteinen kokapen nuklearraren erreferentzia da; ez du TFen RNA ugaritasuna edo kausa-jarduera ondorioztatzen. Hiru Tos9 identitate ebatzi gabe daude."},"mDrop-seq 仅收录核对过的酿酒酵母图示与正文证据；未混入其他物种或从图片估算表达量。":{"en":"mDrop-seq includes only checked S. cerevisiae figure and text evidence; no other species or digitised abundance values are included.","fr":"mDrop-seq ne comprend que les figures et textes vérifiés de S. cerevisiae ; aucune autre espèce ni estimation d’abondance tirée des images.","es":"mDrop-seq incluye solo figuras y texto verificados de S. cerevisiae; sin otras especies ni abundancias estimadas de imágenes.","eu":"mDrop-seq-ek S. cerevisiae-ren egiaztatutako irudi- eta testu-ebidentzia soilik dakar; beste espezierik edo irudietatik estimatutako ugaritasunik gabe."},"Jackson 2020（GSE125162）单细胞数据的再分析；在每个亚群内按TF缺失基因型汇总计数，用DESeq2比较氮源条件内的亚群。保留作者亚群编号。":{"en":"Reanalysis of Jackson 2020 scRNA-seq (GSE125162): counts were aggregated by TF-deletion genotype within each subpopulation and compared with DESeq2 within each nitrogen condition. Original subgroup identifiers are retained.","fr":"Réanalyse du scRNA-seq de Jackson 2020 (GSE125162) : comptages agrégés par génotype de délétion de TF dans chaque sous-population, puis comparaison DESeq2 dans chaque condition azotée. Identifiants originaux conservés.","es":"Reanálisis de scRNA-seq de Jackson 2020 (GSE125162): recuentos agregados por genotipo de deleción de TF dentro de cada subpoblación y comparados con DESeq2 dentro de cada condición nitrogenada. Se conservan los identificadores originales.","eu":"Jackson 2020ko scRNA-seq datuen berranalisia (GSE125162): kontaketak TF-delezioaren genotipoaren arabera batu ziren azpipopulazio bakoitzean, eta DESeq2rekin alderatu nitrogeno-baldintza bakoitzean. Jatorrizko azpitalde-identifikatzaileak gordetzen dira."},"这是来源条件下的差异关联候选，并非独立新scRNA实验、通用G0标记或1011群体的表达高低。来源以不同TF缺失基因型构成比较单位，不能将这些单位当作本项目独立培养重复。原始log2FC方向仅对应所列对比。":{"en":"These are context-specific differential-association candidates, not an independent new scRNA experiment, universal G0 markers, or expression rankings in the 1011 population. TF-deletion genotypes used in the source comparison are not independent culture replicates for this project. Original log2FC signs apply only to the stated contrasts.","fr":"Candidats associés à une différence dans le contexte source, sans nouvelle expérience scRNA indépendante, spécificité G0 universelle ni classement d’expression de la population 1011. Les génotypes de délétion de TF ne sont pas des cultures indépendantes pour ce projet. Le signe du log2FC concerne uniquement le contraste indiqué.","es":"Son candidatos de asociación diferencial en el contexto original, no un experimento scRNA independiente, marcadores G0 universales ni un orden de expresión en la población 1011. Los genotipos de deleción de TF no son réplicas de cultivo independientes de este proyecto. El signo de log2FC solo corresponde al contraste indicado.","eu":"Jatorrizko testuinguruko asoziazio diferentzialaren hautagaiak dira, ez scRNA esperimentu independente berria, G0 markatzaile unibertsalak edo 1011 populazioko espresio-sailkapena. Iturburuko TF-delezio genotipoak ez dira proiektu honetako kultura-erreplika independenteak. Log2FC zeinuak adierazitako konparaziorako dira soilik."},"酵母scRNA-seq再分析；按基因型和亚群汇总的DESeq2比较":{"en":"Yeast scRNA-seq reanalysis; DESeq2 on genotype-by-subpopulation aggregates","fr":"Réanalyse scRNA-seq de levure ; DESeq2 sur agrégats génotype × sous-population","es":"Reanálisis de scRNA-seq de levadura; DESeq2 sobre agregados genotipo × subpoblación","eu":"Legamiaren scRNA-seq berranalisia; DESeq2 genotipo × azpipopulazio agregatuetan"},"脯氨酸条件P2较P1升高的RNA候选（2024）":{"en":"RNA candidates higher in proline P2 than P1 (2024)","fr":"Candidats ARN plus élevés en proline P2 que P1 (2024)","es":"Candidatos de ARN mayores en prolina P2 que P1 (2024)","eu":"Prolinan P2n P1en baino RNA altuagoko hautagaiak (2024)"},"脯氨酸条件P2较P1降低的RNA候选（2024）":{"en":"RNA candidates lower in proline P2 than P1 (2024)","fr":"Candidats ARN plus faibles en proline P2 que P1 (2024)","es":"Candidatos de ARN menores en prolina P2 que P1 (2024)","eu":"Prolinan P2n P1en baino RNA baxuagoko hautagaiak (2024)"},"谷氨酰胺条件G2较G1升高的RNA候选（2024）":{"en":"RNA candidates higher in glutamine G2 than G1 (2024)","fr":"Candidats ARN plus élevés en glutamine G2 que G1 (2024)","es":"Candidatos de ARN mayores en glutamina G2 que G1 (2024)","eu":"Glutaminan G2n G1en baino RNA altuagoko hautagaiak (2024)"},"谷氨酰胺条件G2较G1降低的RNA候选（2024）":{"en":"RNA candidates lower in glutamine G2 than G1 (2024)","fr":"Candidats ARN plus faibles en glutamine G2 que G1 (2024)","es":"Candidatos de ARN menores en glutamina G2 que G1 (2024)","eu":"Glutaminan G2n G1en baino RNA baxuagoko hautagaiak (2024)"},"TF核定位参考：脯氨酸与谷氨酰胺（2024）":{"en":"TF nuclear-localization reference: proline versus glutamine (2024)","fr":"Référence de localisation nucléaire des TF : proline versus glutamine (2024)","es":"Referencia de localización nuclear de TF: prolina frente a glutamina (2024)","eu":"TFen kokapen nuklearraren erreferentzia: prolina versus glutamina (2024)"},"TF核定位参考：脯氨酸低与高亚群（2024）":{"en":"TF nuclear-localization reference: proline low versus high subpopulations (2024)","fr":"Référence de localisation nucléaire des TF : sous-populations faible et élevée en proline (2024)","es":"Referencia de localización nuclear de TF: subpoblaciones baja y alta en prolina (2024)","eu":"TFen kokapen nuklearraren erreferentzia: prolinako azpipopulazio baxua versus altua (2024)"},"TF核定位参考：两种氮源的低亚群（2024）":{"en":"TF nuclear-localization reference: low subpopulations across nitrogen sources (2024)","fr":"Référence de localisation nucléaire des TF : sous-populations faibles selon la source d’azote (2024)","es":"Referencia de localización nuclear de TF: subpoblaciones bajas entre fuentes de nitrógeno (2024)","eu":"TFen kokapen nuklearraren erreferentzia: nitrogeno-iturrien arteko azpipopulazio baxuak (2024)"},"氮源转变后TF-GFP蛋白成像；保留作者Table 4的核定位相对排名及各时间点字段。":{"en":"TF-GFP protein imaging after nitrogen-source shifts; author Table 4 nuclear-localization ranks and timepoint fields are retained.","fr":"Imagerie de protéines TF-GFP après changement de source d’azote ; rangs de localisation nucléaire et temps du tableau 4 conservés.","es":"Imagen de proteínas TF-GFP tras cambios de fuente de nitrógeno; se conservan rangos de localización nuclear y tiempos de la Tabla 4.","eu":"TF-GFP proteinen irudiak nitrogeno-iturria aldatu ondoren; 4. taulako kokapen nuklearreko sailkapenak eta denbora-eremuak gordetzen dira."},"蛋白核定位参考不等于TF的RNA表达方向、转录因子活性因果证据或RNA状态特异marker。排名只在来源对比和时间点内解释，不是1011表达排名。":{"en":"Protein nuclear localization does not establish TF RNA-expression direction, causal TF activity, or an RNA state-specific marker. Ranks apply only within source contrasts and timepoints, not as 1011 expression ranks.","fr":"La localisation nucléaire protéique ne prouve ni le sens d’expression de l’ARN du TF, ni une activité causale, ni un marqueur ARN spécifique. Les rangs concernent uniquement les contrastes et temps sources, pas l’expression dans 1011.","es":"La localización nuclear de proteínas no demuestra dirección del ARN del TF, actividad causal ni un marcador de ARN específico. Los rangos solo se interpretan en los contrastes y tiempos originales, no como expresión de 1011.","eu":"Proteinen kokapen nuklearrak ez du TFaren RNA-espresioaren norabidea, jarduera kausala edo egoerako RNA markatzaile espezifikoa frogatzen. Sailkapenak jatorrizko konparazio eta uneetarako dira, ez 1011eko espresio-sailkapenak."},"TF-GFP蛋白核定位成像":{"en":"TF-GFP protein nuclear-localization imaging","fr":"Imagerie de localisation nucléaire de protéines TF-GFP","es":"Imagen de localización nuclear de proteínas TF-GFP","eu":"TF-GFP proteinen kokapen nuklearraren irudiak"},"这是原研究S. cerevisiae的情境化图示证据；未从图中估读表达量或特异性。应激信号不能单独确定为处理伪影；组蛋白旁系同源基因须检查可比对性。未导入文中的Candida标记。":{"en":"Context-specific figure evidence from S. cerevisiae in the source study; expression values and specificity are not estimated from plots. Stress signals alone cannot establish handling artifacts; histone paralogs require mappability checks. Candida markers are excluded.","fr":"Preuve graphique contextuelle chez S. cerevisiae ; aucune expression ou spécificité n’est estimée depuis les figures. Un signal de stress ne prouve pas un artefact de manipulation ; vérifier l’alignabilité des paralogues d’histones. Marqueurs Candida exclus.","es":"Evidencia gráfica contextual de S. cerevisiae; no se estiman expresión ni especificidad a partir de figuras. El estrés por sí solo no demuestra artefactos de manipulación; comprobar mapeabilidad de parálogos de histonas. Se excluyen marcadores de Candida.","eu":"Iturburuko S. cerevisiae-ren testuinguruko irudi-ebidentzia; ez dira espresioa edo espezifikotasuna irudietatik estimatzen. Estres-seinaleek bakarrik ez dute manipulazio-artefakturik frogatzen; histona-paralogoen mapagarritasuna aztertu. Candida markatzaileak baztertzen dira."},"S. cerevisiae mDrop-seq；原文图示RNA关联":{"en":"S. cerevisiae mDrop-seq; source-figure RNA association","fr":"mDrop-seq de S. cerevisiae ; association ARN illustrée dans l’article","es":"mDrop-seq de S. cerevisiae; asociación de ARN de las figuras originales","eu":"S. cerevisiae mDrop-seq; jatorrizko irudiko RNA-asoziazioa"},"S期组蛋白RNA关联（mDrop-seq）":{"en":"S-phase histone RNA association (mDrop-seq)","fr":"Association ARN des histones à la phase S (mDrop-seq)","es":"Asociación de ARN de histonas con fase S (mDrop-seq)","eu":"S faseko histona-RNA asoziazioa (mDrop-seq)"},"潜在处理应激RNA程序（mDrop-seq）":{"en":"Potential handling-stress RNA program (mDrop-seq)","fr":"Programme ARN de stress potentiel de manipulation (mDrop-seq)","es":"Programa de ARN de posible estrés de manipulación (mDrop-seq)","eu":"Manipulazio-estres posiblearen RNA programa (mDrop-seq)"},"细胞壁与出芽RNA程序（mDrop-seq）":{"en":"Cell-wall and budding RNA program (mDrop-seq)","fr":"Programme ARN de paroi et bourgeonnement (mDrop-seq)","es":"Programa de ARN de pared celular y gemación (mDrop-seq)","eu":"Zelula-pareta eta gemazioaren RNA programa (mDrop-seq)"},"热应激RNA响应候选（mDrop-seq）":{"en":"Heat-stress RNA-response candidates (mDrop-seq)","fr":"Candidats ARN de réponse au stress thermique (mDrop-seq)","es":"Candidatos de ARN de respuesta al estrés térmico (mDrop-seq)","eu":"Bero-estresaren RNA-erantzunaren hautagaiak (mDrop-seq)"},"热应激拟时序分支RNA关联（mDrop-seq）":{"en":"Heat-stress pseudotime-branch RNA association (mDrop-seq)","fr":"Association ARN aux branches de pseudotemps du stress thermique (mDrop-seq)","es":"Asociación de ARN con ramas de pseudotiempo de estrés térmico (mDrop-seq)","eu":"Bero-estresaren pseudodenbora-adarreko RNA-asoziazioa (mDrop-seq)"},"预处理保留率与失败原因":{"en":"Preprocessing retention and failure reasons","fr":"Rétention et causes de rejet du prétraitement","es":"Retención y motivos de descarte del preprocesamiento","eu":"Aurreprozesamenduko atxikipena eta baztertze-arrazoiak"},"记录处理前后read数、碱基数及各过滤失败类别；剪切事件与丢弃read分开。":{"en":"Record reads and bases before and after processing and each filtering failure category; separate trimming events from discarded reads.","fr":"Consigner les lectures et bases avant et après traitement ainsi que chaque cause de rejet ; distinguer rognage et élimination.","es":"Registrar lecturas y bases antes y después del procesamiento y cada motivo de descarte; separar recorte y eliminación.","eu":"Erregistratu irakurketak eta baseak prozesatu aurretik eta ondoren, eta baztertze-arrazoi bakoitza; bereizi mozketa eta ezabaketa."},"poly-G尾与两色测序伪影":{"en":"Poly-G tails and two-colour artefacts","fr":"Queues poly-G et artefacts de séquençage bicolore","es":"Colas poly-G y artefactos de secuenciación de dos colores","eu":"Poly-G isatsak eta bi koloreko sekuentziazio-artefaktuak"},"按read角色记录末端G富集、连续G长度及处理前后变化，并核对测序平台。":{"en":"Record terminal G enrichment, G-run lengths and preprocessing changes by read role, and verify the sequencing platform.","fr":"Consigner l’enrichissement terminal en G, les longueurs de séries de G et leur évolution, selon le rôle de lecture et la plateforme.","es":"Registrar enriquecimiento terminal en G, longitud de rachas de G y cambios según la función de lectura y la plataforma.","eu":"Erregistratu amaierako G aberastasuna, G segiden luzerak eta aldaketak irakurketaren funtzioaren eta plataformaren arabera."},"cDNA双端配对与插入片段结构":{"en":"cDNA mate consistency and insert structure","fr":"Cohérence des paires ADNc et structure des inserts","es":"Coherencia de pares de ADNc y estructura del inserto","eu":"cDNA bikoteen koherentzia eta txertakinen egitura"},"仅对两个mate均测量cDNA的文库，记录配对方向、单端失配、跨contig配对和片段长度分布。":{"en":"For libraries with cDNA in both mates, record pair orientation, singletons, cross-contig pairs and fragment-length distributions.","fr":"Pour les bibliothèques dont les deux mates mesurent l’ADNc, consigner orientation, singletons, paires intercontigs et tailles de fragments.","es":"En bibliotecas con ADNc en ambos mates, registrar orientación, singletons, pares entre contigs y longitudes de fragmentos.","eu":"Bi mateetan cDNA neurtzen duten liburutegietan, erregistratu orientazioa, bikoterik gabeko irakurketak, contig arteko bikoteak eta fragmentuen luzerak."},"RNA区域的比对碱基组成":{"en":"Aligned-base composition across RNA regions","fr":"Composition des bases alignées par région ARN","es":"Composición de bases alineadas por región de ARN","eu":"Lerrokatutako baseen osaera RNA eskualdeetan"},"保存rRNA、CDS、UTR、内含子和基因间的比对碱基比例，并另存可用mRNA碱基比例。":{"en":"Retain aligned-base fractions for rRNA, CDS, UTR, intronic and intergenic regions, plus the separately defined usable-mRNA fraction.","fr":"Conserver les fractions de bases alignées par région et la fraction distincte de bases d’ARNm utilisables.","es":"Conservar las fracciones de bases alineadas por región y la fracción definida por separado de bases de ARNm utilizables.","eu":"Gorde eskualde bakoitzeko lerrokatutako baseen frakzioak eta bereiz definitutako mRNA base erabilgarrien frakzioa."},"RSeQC区域tag组成与未分配量":{"en":"RSeQC feature-tag composition and unassigned tags","fr":"Composition régionale des tags RSeQC et tags non attribués","es":"Composición regional de tags de RSeQC y tags sin asignar","eu":"RSeQC eskualde-tag-en osaera eta esleitu gabeko tag-ak"},"保存RSeQC的Total Reads、Total Tags、Total Assigned Tags及各区域Tag_count，明确其split-read计数单位。":{"en":"Retain RSeQC Total Reads, Total Tags, Total Assigned Tags and regional Tag_count with its split-read counting unit.","fr":"Conserver Total Reads, Total Tags, Total Assigned Tags et Tag_count avec leur unité de comptage des lectures scindées.","es":"Conservar Total Reads, Total Tags, Total Assigned Tags y Tag_count indicando su unidad de lecturas divididas.","eu":"Gorde Total Reads, Total Tags, Total Assigned Tags eta Tag_count, zatitutako irakurketen zenbaketa-unitatea zehaztuta."},"下游工具的BAM语义兼容性":{"en":"BAM semantic compatibility with downstream tools","fr":"Compatibilité sémantique BAM avec les outils en aval","es":"Compatibilidad semántica BAM con herramientas posteriores","eu":"BAM semantikaren bateragarritasuna ondorengo tresnekin"},"逐工具核对所需tag、feature编码、barcode规则、排序与参考版本，而不只检查tag是否存在。":{"en":"For each downstream tool, verify tag semantics, feature coding, barcode rules, sorting and reference version, not merely tag presence.","fr":"Vérifier pour chaque outil la sémantique des tags, les codes de régions, les barcodes, le tri et la référence.","es":"Verificar para cada herramienta la semántica de tags, códigos de región, barcodes, ordenación y referencia.","eu":"Egiaztatu tresna bakoitzerako tag-en semantika, eskualde-kodeak, barcode-ak, ordena eta erreferentzia."},"read抽样后的UMI与基因发现曲线":{"en":"UMI and gene yield after read resampling","fr":"Rendement UMI et gènes après rééchantillonnage des lectures","es":"Rendimiento de UMI y genes tras remuestrear lecturas","eu":"UMI eta geneen errendimendua irakurketak birlagindu ondoren"},"基于分子read支持或成对原始read抽样，重新计算不同测序覆盖下可保留的UMI与基因数。":{"en":"Use molecule read support or paired raw-read sampling to recompute retained UMIs and genes at different sequencing coverages.","fr":"À partir des lectures par molécule ou d’un sous-échantillonnage apparié, recalculer les UMI et gènes conservés à différentes couvertures.","es":"Usar soporte de lecturas por molécula o muestreo de pares para recalcular UMI y genes retenidos con distintas coberturas.","eu":"Erabili molekulako irakurketa-euskarria edo bikoteko laginketa, estaldura desberdinetan atxikitako UMIak eta geneak berriz kalkulatzeko."},"计数器之间的分子与基因一致性":{"en":"Molecule and gene agreement across quantifiers","fr":"Concordance des molécules et gènes entre quantificateurs","es":"Concordancia molecular y génica entre cuantificadores","eu":"Kuantifikatzaileen arteko molekula- eta gene-adostasuna"},"在参考、细胞、feature和UMI规则对齐后，比较计数、检出与候选噪音结论对计数器的敏感性。":{"en":"After aligning reference, cells, features and UMI rules, compare count, detection and candidate-noise sensitivity across quantifiers.","fr":"Après harmonisation de la référence, des cellules, des features et des règles UMI, comparer comptages, détection et conclusions sur le bruit.","es":"Tras armonizar referencia, células, features y reglas UMI, comparar recuentos, detección y conclusiones sobre ruido.","eu":"Erreferentzia, zelulak, feature-ak eta UMI arauak bateratu ondoren, alderatu zenbaketak, detekzioa eta zaratari buruzko ondorioak."},"定位进入比对前的信息损失。":{"en":"Locate information lost before alignment.","fr":"Localiser les pertes d’information avant alignement.","es":"Localizar pérdidas de información antes del alineamiento.","eu":"Kokatu lerrokatzearen aurreko informazio-galerak."},"辨别末端测序伪影及不必要剪切。":{"en":"Identify terminal sequencing artefacts and unnecessary trimming.","fr":"Repérer les artefacts terminaux et le rognage inutile.","es":"Identificar artefactos terminales y recortes innecesarios.","eu":"Identifikatu amaierako artefaktuak eta alferrikako mozketak."},"发现配对错误与异常片段结构。":{"en":"Detect pairing errors and unusual fragment structure.","fr":"Détecter les erreurs d’appariement et les structures inhabituelles.","es":"Detectar errores de emparejamiento y estructuras inusuales.","eu":"Detektatu bikotetze-akatsak eta fragmentu-egitura ezohikoak."},"把碱基层RNA构成与read、UMI构成分开。":{"en":"Separate base-level RNA composition from read and UMI composition.","fr":"Distinguer la composition en bases de celle en lectures et UMI.","es":"Separar la composición por bases de la composición por lecturas y UMI.","eu":"Bereizi baseen osaera irakurketen eta UMIen osaeratik."},"审计区域证据及未被参考分类的部分。":{"en":"Audit regional evidence and the fraction unclassified by the reference.","fr":"Auditer les régions et la fraction non classée par la référence.","es":"Auditar regiones y la fracción no clasificada por la referencia.","eu":"Auditatu eskualdeak eta erreferentziak sailkatu gabeko zatia."},"避免BAM可读却被下游误解释。":{"en":"Prevent downstream misinterpretation of a readable BAM.","fr":"Éviter la mauvaise interprétation d’un BAM pourtant lisible.","es":"Evitar la interpretación incorrecta de un BAM legible.","eu":"Saihestu irakur daitekeen BAM baten interpretazio okerra."},"区分测序深度不足与已接近饱和。":{"en":"Distinguish insufficient sequencing depth from near saturation.","fr":"Distinguer une profondeur insuffisante d’une quasi-saturation.","es":"Distinguir profundidad insuficiente de saturación próxima.","eu":"Bereizi sekuentziazio-sakonera eskasa eta ia asetasuna."},"识别依赖某种分配规则的表达噪音候选。":{"en":"Identify expression-noise candidates sensitive to assignment rules.","fr":"Repérer les candidats de bruit sensibles aux règles d’attribution.","es":"Identificar candidatos de ruido sensibles a las reglas de asignación.","eu":"Identifikatu esleipen-arauekiko sentikorrak diren zarata-hautagaiak."},"双端汇总可能按两个mate计数；barcode read不能自动按普通cDNA处理。":{"en":"Paired summaries may count both mates; barcode reads need their own processing rules.","fr":"Les résumés appariés peuvent compter les deux mates ; traiter les barcodes selon leurs propres règles.","es":"Los resúmenes pueden contar ambos mates; los barcodes requieren reglas propias.","eu":"Laburpenek bi mateak zenbatu ditzakete; barcode irakurketek arau propioak behar dituzte."},"软件原生失败类别遵循其过滤顺序，不能解释为互相独立的失效概率。":{"en":"Native failure categories follow the filtering order; they are not independent failure probabilities.","fr":"Les catégories suivent l’ordre de filtrage et ne sont pas des probabilités indépendantes.","es":"Las categorías siguen el orden de filtrado y no son probabilidades independientes.","eu":"Kategoriek iragazkien ordenari jarraitzen diote; ez dira probabilitate independenteak."},"不把所有G-rich序列判为伪影；fastp没有保证输出这个项目同名比例字段。":{"en":"G-rich sequence is not automatically an artefact; fastp does not guarantee this project-defined fraction as a native field.","fr":"Une séquence riche en G n’est pas forcément un artefact ; cette fraction n’est pas un champ natif garanti de fastp.","es":"Una secuencia rica en G no implica artefacto; fastp no garantiza esta fracción como campo nativo.","eu":"G ugariko sekuentzia ez da beti artefaktua; fastp-ek ez du frakzio hau berezko eremu gisa bermatzen."},"R1为barcode、R2为cDNA的技术不适用cDNA配对指标。":{"en":"cDNA pair metrics do not apply when R1 is the barcode and R2 is cDNA.","fr":"Ces métriques ne s’appliquent pas si R1 porte le barcode et R2 l’ADNc.","es":"Estas métricas no aplican si R1 es barcode y R2 es ADNc.","eu":"Metrika hauek ez dira aplikatzen R1 barcode-a eta R2 cDNA direnean."},"RNA跨内含子比对的基因组TLEN不等于转录本片段长度；结果受aligner定义影响。":{"en":"Genomic TLEN across introns differs from transcript fragment length and depends on aligner conventions.","fr":"Le TLEN génomique traversant des introns diffère de la longueur du fragment transcrit et dépend de l’aligneur.","es":"El TLEN genómico sobre intrones difiere de la longitud del fragmento transcrito y depende del alineador.","eu":"Introiak zeharkatzen dituen TLEN genomikoa ez da transkripto-fragmentuaren luzera eta lerrokatzailearen araberakoa da."},"没有提供rRNA intervals时，不把缺失rRNA指标当作零。":{"en":"Without rRNA intervals, missing rRNA metrics are not zero.","fr":"Sans intervalles ARNr, une métrique manquante ne vaut pas zéro.","es":"Sin intervalos de ARNr, una métrica ausente no equivale a cero.","eu":"rRNA tarterik gabe, falta den metrika ez da zero."},"端标签文库与全长文库的覆盖期望不同。":{"en":"End-tag and full-length libraries have different coverage expectations.","fr":"Les couvertures attendues diffèrent entre bibliothèques terminales et pleine longueur.","es":"La cobertura esperada difiere entre bibliotecas terminales y de longitud completa.","eu":"Espero den estaldura desberdina da muturreko eta luzera osoko liburutegietan."},"一个剪接read可产生多个tag；嵌套的TSS/TES窗口不能重复相加。":{"en":"One spliced read can produce several tags; nested TSS/TES windows must not be summed twice.","fr":"Une lecture épissée peut produire plusieurs tags ; ne pas additionner les fenêtres TSS/TES imbriquées.","es":"Una lectura empalmada puede producir varios tags; no sumar dos veces ventanas TSS/TES anidadas.","eu":"Irakurketa moztu batek hainbat tag sor ditzake; ez batu birritan TSS/TES leiho habiaratuak."},"tag是此模块的split-read片段单位，与SAM可选标签及UMI无关。":{"en":"Here tag means a split-read segment, distinct from a SAM optional tag or UMI.","fr":"Ici tag désigne un segment de lecture, distinct d’un tag SAM ou UMI.","es":"Aquí tag es un segmento de lectura, distinto de un tag SAM o UMI.","eu":"Hemen tag irakurketa-zatia da, ez SAM etiketa edo UMI bat."},"RSeQC sc_bamStat.py以Cell Ranger语义为基础；STARsolo的GX或sF不能直接改名当RE或xf。":{"en":"RSeQC sc_bamStat.py expects Cell Ranger semantics; renaming STARsolo GX/sF to RE/xf is not valid.","fr":"sc_bamStat.py attend la sémantique Cell Ranger ; renommer GX/sF de STARsolo en RE/xf est invalide.","es":"sc_bamStat.py espera semántica Cell Ranger; no basta renombrar GX/sF de STARsolo como RE/xf.","eu":"sc_bamStat.py-k Cell Ranger semantika espero du; ezin dira STARsolo GX/sF RE/xf bihurtu izena aldatuta."},"UMI矩阵抽稀不等于测序read抽样；molecule_info.h5方法需兼容的分子支持格式。":{"en":"UMI thinning differs from sequencing-read sampling; molecule_info.h5 methods require a compatible read-support format.","fr":"La raréfaction UMI diffère du sous-échantillonnage des lectures ; molecule_info.h5 exige un format compatible.","es":"Reducir UMI difiere de muestrear lecturas; molecule_info.h5 requiere un formato compatible.","eu":"UMIak gutxitzea ez da irakurketak lagintzea; molecule_info.h5-ek formatu bateragarria behar du."},"固定细胞集合与重新识别细胞的两种曲线分别记录。":{"en":"Report curves with fixed cells and with repeated cell calling separately.","fr":"Séparer les courbes à cellules fixes de celles avec rappel des cellules.","es":"Separar curvas con células fijas de curvas con nueva identificación celular.","eu":"Bereiz eman zelula finkoekin eta berriz identifikatutako zelulekin egindako kurbak."},"跨软件一致不是独立真值；GeneFull、USA及spliced/unspliced定义先对齐。":{"en":"Agreement across tools is not ground truth; first align GeneFull, USA and spliced/unspliced definitions.","fr":"L’accord entre outils n’est pas une vérité indépendante ; harmoniser GeneFull, USA et épissé/non épissé.","es":"La concordancia no es una verdad independiente; armonizar primero GeneFull, USA y empalmado/no empalmado.","eu":"Tresnen arteko adostasuna ez da egia independentea; lehenik bateratu GeneFull, USA eta spliced/unspliced definizioak."},"不要求把所有计数器作为主流程同时运行；可对代表性文库和重点候选审计。":{"en":"This comparison can use representative libraries and priority candidates; every quantifier need not be a primary workflow.","fr":"La comparaison peut cibler des bibliothèques représentatives et des candidats prioritaires.","es":"La comparación puede centrarse en bibliotecas representativas y candidatos prioritarios.","eu":"Konparazioa liburutegi adierazgarrietan eta lehentasunezko hautagaietan egin daiteke."},"同一read单位的输入reads或碱基":{"en":"Input reads or bases under one counting convention","fr":"Lectures ou bases d’entrée selon une convention unique","es":"Lecturas o bases de entrada con una convención única","eu":"Sarrerako irakurketak edo baseak zenbaketa-arau berarekin"},"同read角色、同处理阶段检查的reads":{"en":"Reads assessed in the same role and processing stage","fr":"Lectures du même rôle et de la même étape","es":"Lecturas con la misma función y etapa","eu":"Funtzio eta etapa berean aztertutako irakurketak"},"符合所声明过滤条件的cDNA pairs":{"en":"cDNA pairs satisfying the declared filters","fr":"Paires ADNc satisfaisant les filtres déclarés","es":"Pares de ADNc que cumplen los filtros declarados","eu":"Adierazitako iragazkiak betetzen dituzten cDNA bikoteak"},"区域比例以PF_ALIGNED_BASES为分母；PCT_USABLE_BASES以PF_BASES为分母":{"en":"Regional fractions use PF_ALIGNED_BASES; PCT_USABLE_BASES uses PF_BASES","fr":"Fractions régionales : PF_ALIGNED_BASES ; PCT_USABLE_BASES : PF_BASES","es":"Fracciones regionales: PF_ALIGNED_BASES; PCT_USABLE_BASES: PF_BASES","eu":"Eskualde-frakzioak: PF_ALIGNED_BASES; PCT_USABLE_BASES: PF_BASES"},"各区域Tag_count除以声明的Total Tags或Total Assigned Tags；两者不混用":{"en":"Regional Tag_count divided by declared Total Tags or Total Assigned Tags; keep these denominators distinct","fr":"Tag_count régional divisé par Total Tags ou Total Assigned Tags, sans confondre les dénominateurs","es":"Tag_count regional dividido por Total Tags o Total Assigned Tags, sin confundir denominadores","eu":"Eskualdeko Tag_count zati Total Tags edo Total Assigned Tags, izendatzaileak nahastu gabe"},"预先选择的下游工具及必要字段":{"en":"Prespecified downstream tools and required fields","fr":"Outils en aval et champs requis prédéfinis","es":"Herramientas posteriores y campos requeridos predefinidos","eu":"Aurrez aukeratutako ondorengo tresnak eta beharrezko eremuak"},"各抽样比例对应的实际eligible read数":{"en":"Actual eligible read count at each sampling fraction","fr":"Nombre de lectures admissibles à chaque fraction","es":"Número de lecturas elegibles en cada fracción","eu":"Frakzio bakoitzeko irakurketa onargarrien benetako kopurua"},"共同可比较的细胞与feature集合":{"en":"Common comparable cells and feature universe","fr":"Cellules et features communes comparables","es":"Células y features comunes comparables","eu":"Konpara daitezkeen zelula eta feature komunak"},"长度／比例":{"en":"Length / fraction","fr":"Longueur / fraction","es":"Longitud / fracción","eu":"Luzera / frakzioa"},"计数／nt":{"en":"Count / nt","fr":"Nombre / nt","es":"Recuento / nt","eu":"Kopurua / nt"},"碱基比例":{"en":"Base fraction","fr":"Fraction de bases","es":"Fracción de bases","eu":"Base-frakzioa"},"tag计数／比例":{"en":"Tag count / fraction","fr":"Nombre / fraction de tags","es":"Recuento / fracción de tags","eu":"Tag kopurua / frakzioa"},"兼容性审计":{"en":"Compatibility audit","fr":"Audit de compatibilité","es":"Auditoría de compatibilidad","eu":"Bateragarritasun-auditoria"},"差值／检出一致性":{"en":"Difference / detection agreement","fr":"Différence / concordance de détection","es":"Diferencia / concordancia de detección","eu":"Diferentzia / detekzio-adostasuna"},"同一捕获文库的多个lane不是独立文库；真实碰撞与复用barcode也会共享组合，不能把该比例直接命名为index hopping率。":{"en":"Lanes of one capture are not independent libraries; collisions or reused barcodes can also share keys, so this fraction is not an index-hopping rate.","fr":"Les lanes d’une capture ne sont pas indépendantes ; collisions et barcodes réutilisés partagent aussi des clés. Cette fraction n’est pas un taux de saut d’index.","es":"Los lanes de una captura no son bibliotecas independientes; colisiones y barcodes reutilizados comparten claves. Esta fracción no es una tasa de index hopping.","eu":"Capture bereko lane-ak ez dira independenteak; talkek eta barcode berrerabiliek ere gakoak partekatzen dituzte. Frakzio hau ez da index hopping tasa."},"STARsolo Summary.csv的唯一gene归属比例以输入read units为分母；本项目以已比对reads为分母的条件比例必须另算，不直接复制该列。":{"en":"STARsolo divides the unique-gene summary by input read units; the mapped-read conditional fraction must be derived separately.","fr":"STARsolo utilise les unités de lecture d’entrée ; recalculer séparément la fraction conditionnelle aux lectures alignées.","es":"STARsolo usa unidades de lectura de entrada; calcular aparte la fracción condicional a lecturas alineadas.","eu":"STARsolo-k sarrerako irakurketa-unitateak erabiltzen ditu; lerrokatutakoen frakzio baldintzatua bereiz kalkulatu."},"该相减只用于STARsolo同一run中明确包含unique项的UniqueAndMult矩阵；不推广到不同软件或不同UMI过滤规则。":{"en":"This subtraction applies only to same-run STARsolo UniqueAndMult matrices that include the unique counts, not different software or UMI rules.","fr":"Cette soustraction ne vaut que pour les matrices STARsolo du même run comprenant les comptes uniques.","es":"La resta solo vale para matrices STARsolo del mismo run que incluyen recuentos únicos.","eu":"Kenketa run bereko STARsolo matrizeetarako bakarrik da, unique zenbaketak barne dituztenean."},"参考缺失、ID未映射、矩阵轴缺失与真实观测零值分别记录；RNA不检出不能证明基因组缺失。":{"en":"Keep reference absence, unmapped IDs, missing matrix axes and observed zeros separate; RNA non-detection does not establish genomic absence.","fr":"Séparer absence de référence, identifiants non mappés, axes manquants et zéros ; une non-détection ARN ne prouve pas une absence génomique.","es":"Separar ausencia de referencia, IDs sin mapear, ejes ausentes y ceros; no detectar ARN no demuestra ausencia genómica.","eu":"Bereizi erreferentzia-eza, mapatu gabeko IDak, ardatz faltak eta zeroak; RNA ez detektatzeak ez du absentzia genomikoa frogatzen."},"不同方法的污染参数定义不同；同一输出列不得混装不同方法的分数。":{"en":"Contamination parameters differ by method; do not combine different scores in one output column.","fr":"Les paramètres diffèrent selon la méthode ; ne pas mélanger leurs scores dans une colonne.","es":"Los parámetros difieren por método; no mezclar sus puntuaciones en una columna.","eu":"Parametroak metodoaren araberakoak dira; ez nahastu puntuazioak zutabe berean."},"模型背景与直接空滴计数分别保存；未建模基因不能默认为零背景。":{"en":"Keep model background and directly counted empty droplets separate; unmodelled genes do not imply zero background.","fr":"Séparer fond modélisé et gouttes vides observées ; un gène non modélisé n’a pas nécessairement un fond nul.","es":"Separar fondo modelado y gotas vacías observadas; genes no modelados no implican fondo cero.","eu":"Bereizi modelatutako hondoa eta tanta hutsen zenbaketak; modelatu gabeko geneak ez dira zero hondoa."},"samples对应独立捕获，不是混样池内菌株；同状态或同菌株双细胞可能缺乏可辨识信号。":{"en":"samples identifies captures, not strains inside one pool; same-state or same-strain doublets can be unidentifiable.","fr":"samples désigne les captures, pas les souches d’un pool ; les doublets de même état ou souche peuvent rester indétectables.","es":"samples identifica capturas, no cepas dentro de un pool; dobletes del mismo estado o cepa pueden no identificarse.","eu":"samples-ek capture-ak adierazten ditu, ez pool barruko anduiak; egoera edo andui bereko doubletak identifikaezinak izan daitezke."},"cellSNP-lite输出等位计数，不直接给出菌株身份后验；匿名donor簇须独立匹配已知菌株才可命名。":{"en":"cellSNP-lite supplies allele counts, not strain posteriors; anonymous donor clusters need independent matching before strain naming.","fr":"cellSNP-lite fournit des comptes alléliques, pas des postérieurs de souche ; apparier les clusters anonymes avant de les nommer.","es":"cellSNP-lite aporta recuentos alélicos, no posteriores de cepa; identificar de forma independiente los clusters anónimos antes de nombrarlos.","eu":"cellSNP-lite-k alelo-zenbaketak ematen ditu, ez andui-posteriorrak; kluster anonimoak independenteki identifikatu behar dira izendatzeko."},"跨SNP求和的DP和demuxlet RD.UNIQ可能多次计入同一分子；不得标为细胞内独立分子总数。":{"en":"Summed DP or demuxlet RD.UNIQ can count one molecule at several SNPs; neither is automatically a cell-wide distinct-molecule total.","fr":"DP sommé ou RD.UNIQ peut compter une molécule sur plusieurs SNP ; ce n’est pas automatiquement un total cellulaire de molécules distinctes.","es":"Sumar DP o RD.UNIQ puede contar una molécula en varios SNP; no es automáticamente un total celular de moléculas únicas.","eu":"DP edo RD.UNIQ batzeak molekula bera hainbat SNPtan zenbatu dezake; ez da automatikoki zelulako molekula bakarren guztizkoa."},"跨菌株的真实RNA组成差异可能影响质量模型；模型分数不等于细胞死亡概率。":{"en":"Real RNA-composition differences among strains can affect QC models; scores are not cell-death probabilities.","fr":"Les différences réelles entre souches influencent le QC ; ces scores ne sont pas des probabilités de mort cellulaire.","es":"Diferencias reales entre cepas pueden afectar el QC; sus puntuaciones no son probabilidades de muerte celular.","eu":"Anduien arteko benetako aldeek QC ereduetan eragin dezakete; puntuazioak ez dira heriotza zelularraren probabilitateak."},"RSeQC read_distribution.py原生输出为Tag_count；一个剪接read可拆成多个tag，不能直接当作此read比例。":{"en":"RSeQC read_distribution.py reports Tag_count; spliced reads can yield several tags, so it cannot directly supply this read fraction.","fr":"read_distribution.py rapporte Tag_count ; une lecture épissée peut produire plusieurs tags, sans fournir directement cette fraction de lectures.","es":"read_distribution.py informa Tag_count; una lectura empalmada puede generar varios tags, por lo que no da esta fracción directamente.","eu":"read_distribution.py-k Tag_count ematen du; irakurketa batek hainbat tag sor ditzake eta ez du irakurketa-frakzio hau zuzenean ematen."},"区域优先级和基因重叠规则必须固定；外显子、内含子、基因间与未定类别共同核对分母。":{"en":"Fix regional priorities and overlap rules; reconcile exonic, intronic, intergenic and unresolved categories against the denominator.","fr":"Fixer priorités et chevauchements ; rapprocher les catégories exoniques, introniques, intergéniques et indéterminées du dénominateur.","es":"Fijar prioridades y solapamientos; conciliar categorías exónicas, intrónicas, intergénicas e indeterminadas con el denominador.","eu":"Finkatu lehentasunak eta gainjartze-arauak; bateratu exoniko, introniko, intergeniko eta ebatzi gabeko kategoriak izendatzailearekin."},"quickcheck检查头部和文件尾，不读取文件中部，也不验证实际坐标排序或索引内容。":{"en":"quickcheck checks the header and file end; it does not inspect the interior, actual coordinate sorting or index contents.","fr":"quickcheck vérifie l’en-tête et la fin, pas l’intérieur, le tri réel ni le contenu de l’index.","es":"quickcheck verifica cabecera y final, no el interior, el orden real ni el índice.","eu":"quickcheck-ek goiburua eta amaiera egiaztatzen ditu, ez barrualdea, benetako ordena edo indizea."},"不能仅从gene×cell UMI矩阵计算read测序饱和度。":{"en":"Read sequencing saturation cannot be calculated from a gene-by-cell UMI matrix alone.","fr":"La saturation en lectures ne se calcule pas à partir de la seule matrice UMI gène-cellule.","es":"La saturación de lecturas no se calcula solo con la matriz UMI gen-célula.","eu":"Irakurketen asetasuna ezin da gene-zelula UMI matrizetik bakarrik kalkulatu."},"饱和度依赖有效read、UMI纠错与feature规则；不同工具定义不自动等价。":{"en":"Saturation depends on eligible reads, UMI correction and feature rules; tool definitions are not automatically equivalent.","fr":"La saturation dépend des lectures, de la correction UMI et des features ; les définitions ne sont pas équivalentes d’office.","es":"La saturación depende de lecturas, corrección UMI y features; las definiciones no son automáticamente equivalentes.","eu":"Asetasuna irakurketen, UMI zuzenketaren eta feature arauen araberakoa da; definizioak ez dira automatikoki baliokideak."},"--soloCellFilter None时STARsolo不输出依赖filteredCells的这些汇总字段；后续只用矩阵运行CellFiltering也没有原始read支持。":{"en":"With --soloCellFilter None, these filtered-cell summaries are absent; matrix-only CellFiltering also lacks original read support.","fr":"Avec --soloCellFilter None, ces résumés sont absents ; CellFiltering sur matrice seule n’a pas les lectures d’origine.","es":"Con --soloCellFilter None faltan estos resúmenes; CellFiltering sobre matriz sola tampoco dispone del soporte original de lecturas.","eu":"--soloCellFilter None aukerarekin laburpen hauek falta dira; matrize hutsezko CellFiltering-ek ere ez du jatorrizko irakurketa-euskarririk."},"序列内容摘要和压缩文件字节校验不是同一指标；应与交付清单使用同一校验算法。":{"en":"Sequence-content digests differ from compressed-file byte checksums; match the delivery manifest algorithm.","fr":"Le résumé des séquences diffère du checksum des octets compressés ; utiliser l’algorithme du manifeste.","es":"El resumen de secuencias difiere del checksum de bytes comprimidos; usar el algoritmo del manifiesto.","eu":"Sekuentzia-laburpena eta fitxategi konprimituaren checksum-a desberdinak dira; erabili entregako algoritmo bera."},"文库；逐细胞值另算":{"en":"Library; per-cell values derived separately","fr":"Bibliothèque ; valeurs cellulaires dérivées séparément","es":"Biblioteca; valores celulares derivados por separado","eu":"Liburutegia; zelulako balioak bereiz kalkulatuta"},"分别记录文件端点检查、完整记录检查、可索引性和区域读取，不能用quickcheck代替全部验证。":{"en":"Record endpoint checks, full-record validation, indexing and regional retrieval separately; quickcheck does not replace them.","fr":"Séparer vérification des extrémités, validation complète, indexation et lecture régionale.","es":"Separar comprobación de extremos, validación completa, indexación y consulta regional.","eu":"Bereizi muturren egiaztapena, erregistro osoen balidazioa, indexazioa eta eskualde-irakurketa."},"原生Summary为文库/feature统计；逐细胞版本需读取分子read支持后另算。":{"en":"The native summary is library/feature-level; per-cell values require separate molecule/read-support aggregation.","fr":"Le résumé natif est par bibliothèque/feature ; les valeurs cellulaires nécessitent une agrégation séparée.","es":"El resumen nativo es por biblioteca/feature; los valores celulares requieren agregación aparte.","eu":"Berezko laburpena liburutegi/feature mailakoa da; zelulako balioek agregazio bereizia behar dute."},"保留原生unique-feature读段分母；外部细胞识别的值另算。":{"en":"Retain the native unique-feature read denominator; derive values for external cell calls separately.","fr":"Conserver le dénominateur natif unique-feature ; recalculer les appels cellulaires externes.","es":"Conservar el denominador nativo unique-feature; recalcular llamadas celulares externas.","eu":"Gorde berezko unique-feature izendatzailea; kanpoko zelula-deietarako bereiz kalkulatu."},"分别保存文件校验、完整解压与FASTQ记录检查；seqkit stats汇总不能代替交付校验。":{"en":"Retain checksums, full decompression and FASTQ checks separately; seqkit stats does not replace delivery verification.","fr":"Conserver checksum, décompression complète et contrôle FASTQ ; seqkit stats ne remplace pas le contrôle de livraison.","es":"Conservar checksum, descompresión y control FASTQ; seqkit stats no sustituye la verificación de entrega.","eu":"Gorde checksum-a, deskonpresio osoa eta FASTQ kontrola; seqkit stats-ek ez du entrega-egiaztapena ordezten."},"计数／比例":{"en":"Count / fraction","fr":"Nombre / proportion","es":"Conteo / proporción","eu":"Zenbaketa / proportzioa"},"末端poly-G处理":{"en":"Terminal poly-G handling","fr":"Traitement des queues poly-G","es":"Procesamiento de colas poly-G","eu":"Muturreko poly-G buztanen tratamendua"},"核对平台和read角色，记录是否自动启用；不对未知CB/UMI结构默认剪切。":{"en":"Verify the platform and read roles, and record whether automatic handling was enabled; do not trim unknown CB/UMI structures by default.","fr":"Vérifiez la plateforme et le rôle des reads, puis consignez l’activation éventuelle du traitement automatique ; ne tronquez pas par défaut les structures CB/UMI inconnues.","es":"Verifica la plataforma y el papel de cada read y registra si se activó el procesamiento automático; no recortes por defecto estructuras CB/UMI desconocidas.","eu":"Egiaztatu plataforma eta read-en rolak, eta erregistratu tratamendu automatikoa aktibatu den; ez moztu egitura ezezaguneko CB/UMI sekuentziak lehenespenez."},"原生处理报告":{"en":"Native processing report","fr":"Rapport natif du traitement","es":"Informe nativo del procesamiento","eu":"Prozesatzearen jatorrizko txostena"},"保存版本、命令、处理前后统计和过滤失败原因。":{"en":"Retain the version, command, statistics before and after processing, and filtering failure reasons.","fr":"Conservez la version, la commande, les statistiques avant et après traitement et les motifs d’exclusion par filtrage.","es":"Conserva la versión, el comando, las estadísticas antes y después del procesamiento y los motivos de exclusión por filtrado.","eu":"Gorde bertsioa, komandoa, prozesatu aurreko eta ondorengo estatistikak eta iragazketan baztertzeko arrazoiak."},"quickcheck只检查头部和EOF，不能证明文件中部、实际排序与索引完全有效。":{"en":"quickcheck checks only the header and EOF; it does not establish that the file interior, actual sorting and index are fully valid.","fr":"quickcheck vérifie uniquement l’en-tête et EOF ; il ne garantit pas la validité du contenu intermédiaire, du tri effectif et de l’index.","es":"quickcheck solo verifica la cabecera y EOF; no garantiza la validez del contenido intermedio, la ordenación real ni el índice.","eu":"quickcheck-ek goiburua eta EOF bakarrik egiaztatzen ditu; ez du bermatzen fitxategiaren barneko edukia, benetako ordenazioa eta indizea guztiz baliozkoak direnik."},"单细胞BAM标签语义":{"en":"Single-cell BAM tag semantics","fr":"Sémantique des tags BAM unicellulaires","es":"Semántica de las etiquetas BAM unicelulares","eu":"Zelula bakarreko BAM etiketen semantika"},"先核对Cell Ranger风格语义与实际BAM；不能只用同名tag通过检查。":{"en":"Compare Cell Ranger tag semantics with the actual BAM first; matching tag names alone do not establish compatibility.","fr":"Comparez d’abord la sémantique des tags Cell Ranger au BAM réel ; des noms de tags identiques ne suffisent pas à établir la compatibilité.","es":"Compara primero la semántica de las etiquetas de Cell Ranger con el BAM real; compartir nombres de etiquetas no basta para demostrar compatibilidad.","eu":"Alderatu lehenik Cell Ranger etiketen semantika benetako BAMarekin; etiketen izenak bat etortzeak ez du bateragarritasuna bermatzen."},"线粒体contig名称":{"en":"Mitochondrial contig name","fr":"Nom du contig mitochondrial","es":"Nombre del contig mitocondrial","eu":"Contig mitokondrialaren izena"},"使用真实酵母参考contig；不默认chrM。":{"en":"Use the contig name in the actual yeast reference; do not assume chrM.","fr":"Utilisez le nom du contig dans la référence de levure effective ; ne supposez pas qu’il s’agit de chrM.","es":"Usa el nombre del contig de la referencia de levadura utilizada; no presupongas chrM.","eu":"Erabili benetako legamia-erreferentziako contig izena; ez hartu chrM lehenetsitzat."},"read_distribution.py输出Tag_count，不是逐read或UMI数；剪接read产生多个tag。":{"en":"read_distribution.py reports Tag_count, not per-read or UMI counts; a spliced read can contribute multiple tags.","fr":"read_distribution.py rapporte Tag_count, pas un nombre de reads ou d’UMI ; un read épissé peut contribuer plusieurs tags.","es":"read_distribution.py informa Tag_count, no conteos de reads ni UMI; un read con empalme puede aportar varias etiquetas.","eu":"read_distribution.py-k Tag_count ematen du, ez read edo UMI kopurua; splicing-a duen read batek hainbat tag sor ditzake."},"sc_bamStat.py需要Cell Ranger风格feature标签；STARsolo BAM应先验证输入契约。":{"en":"sc_bamStat.py requires Cell Ranger-style feature tags; validate the input requirements before using a STARsolo BAM.","fr":"sc_bamStat.py requiert des tags de features de type Cell Ranger ; vérifiez les exigences d’entrée avant d’utiliser un BAM STARsolo.","es":"sc_bamStat.py requiere etiquetas de features de tipo Cell Ranger; verifica los requisitos de entrada antes de usar un BAM de STARsolo.","eu":"sc_bamStat.py-k Cell Ranger motako feature etiketak behar ditu; egiaztatu sarrera-baldintzak STARsolo BAM bat erabili aurretik."},"匹配的酵母rRNA区间":{"en":"Matched yeast rRNA intervals","fr":"Intervalles rRNA de levure concordants","es":"Intervalos de rRNA de levadura concordantes","eu":"Bat datozen legamiaren rRNA tarteak"},"保留contig和参考版本；未提供时rRNA指标不视为零。":{"en":"Retain the contig identifiers and reference version; do not treat rRNA metrics as zero when intervals were not supplied.","fr":"Conservez les identifiants des contigs et la version de référence ; ne considérez pas les métriques rRNA comme nulles si les intervalles n’ont pas été fournis.","es":"Conserva los identificadores de contigs y la versión de referencia; no interpretes las métricas de rRNA como cero si no se proporcionaron los intervalos.","eu":"Gorde contig identifikatzaileak eta erreferentziaren bertsioa; tarterik eman ez bada, ez hartu rRNA metrikak zerotzat."},"read层抽样":{"en":"Read-level subsampling","fr":"Sous-échantillonnage des reads","es":"Submuestreo de reads","eu":"Read mailako azpilaginketa"},"需要兼容的molecule_info.h5及每分子read支持；记录prop与随机种子。":{"en":"Requires a compatible molecule_info.h5 and per-molecule read support; record prop and the random seed.","fr":"Requiert un fichier molecule_info.h5 compatible et le nombre de reads par molécule ; consignez prop et la graine aléatoire.","es":"Requiere un molecule_info.h5 compatible y el soporte de reads por molécula; registra prop y la semilla aleatoria.","eu":"molecule_info.h5 bateragarria eta molekula bakoitzaren read euskarria behar dira; erregistratu prop eta ausazko hazia."}});
window.YV_TERMS=window.YV_TERMS||{};Object.assign(window.YV_TERMS,window.YV_TEXT);
